public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are valid
    if (start[0] < 0 || start[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // Create a boolean array to keep track of the visited n-tersections
    boolean[] visited = new boolean[n * n];

    // Initialize a queue to store the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Mark the current n-tersection as visited
        visited[current[0] * n + current[1]] = true;

        // Add the neighbors of the current n-tersection to the queue
        for (int[] neighbor : paths[current[0] * n + current[1]]) {
            if (!visited[neighbor[0] * n + neighbor[1]]) {
                queue.offer(neighbor);
            }
        }
    }

    // If the ending n-tersection is not reachable, return "cannot be travelled"
    return "cannot be travelled";
}

