public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    int time = 0;

    // Start at node 0
    queue.offer(0);
    visited[0] = true;

    // Breadth-first search
    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        time++;

        // If the current node has an apple, add the time
        if (hasApple[currentNode]) {
            return time;
        }

        // Enqueue the neighbors
        for (int neighbor : edges[currentNode]) {
            if (!visited[neighbor]) {
                queue.offer(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    // If we reach this point, there are no apples
    return 0;
}

